function activateWork(key,index){const data=authorData[key],media=workMedia[key]?.[index],work=data?.works[index];if(!data||!media||!work)return;authorModal.querySelectorAll('.author-modal-works li').forEach((item,i)=>item.classList.toggle('active',i===index));authorVisual.classList.remove('no-image');authorVisual.classList.toggle('white-background',key==='aloisio'&&index===2);authorVisual.style.backgroundImage=`url("${media[0]}")`;authorVisual.setAttribute('role','img');authorVisual.setAttribute('aria-label',media[2]);authorMonogram.textContent='';previewMeta.hidden=false;previewMeta.querySelector('b').textContent=work[0];previewMeta.querySelector('small').textContent=work[1];const source=authorModal.querySelector('.author-modal-source');source.href=media[1];source.setAttribute('aria-label',`Abrir fonte de ${work[0]}`)}
function prepareWorkSelector(key){authorModal.querySelectorAll('.author-modal-works li').forEach((item,index)=>{item.classList.remove('featured');item.tabIndex=0;item.setAttribute('role','button');item.setAttribute('aria-label',`Visualizar ${authorData[key].works[index][0]}`);item.onclick=()=>activateWork(key,index);item.onkeydown=(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();activateWork(key,index)}}});activateWork(key,displayedWorkIndex[key]??0)}
document.querySelectorAll('[data-author]').forEach((card)=>{card.addEventListener('click',()=>prepareWorkSelector(card.dataset.author));card.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' ')setTimeout(()=>prepareWorkSelector(card.dataset.author))})});
